    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 59-year-old man is brought to the clinic by his spouse due to striking behavioral changes over the past 4 years. The spouse reports that the patient has become increasingly socially inappropriate (making crude comments to strangers), shows a profound lack of empathy, has developed a compulsive craving for sweets (**hyperorality**), and repeatedly hoards items. Memory and visuospatial skills remain relatively intact on cognitive testing. Brain MRI reveals **bilateral frontal and anterior temporal lobe** atrophy. Which of the following is the most likely diagnosis?', '["Alzheimer''''s disease \u2014 characterized by early and prominent episodic memory loss with preservation of social behavior until late stages", "Obsessive-compulsive disorder \u2014 characterized by ego-dystonic obsessions and compulsions that the patient recognizes as excessive", "Dementia with Lewy Bodies \u2014 characterized by fluctuating cognition, visual hallucinations, and spontaneous parkinsonism", "Bipolar disorder (manic episode) \u2014 characterized by elevated mood, pressured speech, decreased need for sleep, and grandiosity", "Behavioral variant Frontotemporal Dementia (bvFTD) \u2014 characterized by early personality and behavioral changes (disinhibition, apathy, loss of empathy, hyperorality, compulsive behaviors) with relative preservation of memory and visuospatial skills; caused by frontal and anterior temporal lobe degeneration"]'::jsonb, 4, 'This patient''''s presentation is classic for **behavioral variant Frontotemporal Dementia (bvFTD)**, the most common subtype of FTD. Diagnostic criteria (Rascovsky criteria) require at least 3 of the following 6 features: (1) **Early behavioral disinhibition** — socially inappropriate behavior, loss of manners; (2) **Early apathy/inertia** — loss of motivation, reduced initiative; (3) **Early loss of sympathy/empathy** — diminished response to others'''' needs and feelings; (4) **Early perseverative, stereotyped, or compulsive/ritualistic behavior** — hoarding, repetitive movements; (5) **Hyperorality and dietary changes** — craving sweets, binge eating, attempting to eat inedible objects; (6) **Neuropsychological profile** showing **executive dysfunction with relative sparing of memory and visuospatial function**. Brain MRI shows **frontal and/or anterior temporal** atrophy, often asymmetric. FTD typically has an earlier onset (45-65 years) compared to AD (>65). Treatment is supportive: SSRIs for disinhibition and compulsive behaviors, trazodone for agitation. (Ref: Hazzard''''s Ch. 72; Rascovsky Criteria 2011)'),
    (v_topic_id, 'A 63-year-old male is brought to the clinic by his spouse due to striking behavioral changes over the past 4 years. The spouse reports that the patient has become increasingly socially inappropriate (making crude comments to strangers), shows a profound lack of empathy, has developed a compulsive craving for sweets (**hyperorality**), and repeatedly hoards items. Memory and visuospatial skills remain relatively intact on cognitive testing. Brain MRI reveals **bilateral frontal and anterior temporal lobe** atrophy. Which of the following is the most likely diagnosis?', '["Obsessive-compulsive disorder \u2014 characterized by ego-dystonic obsessions and compulsions that the patient recognizes as excessive", "Alzheimer''''s disease \u2014 characterized by early and prominent episodic memory loss with preservation of social behavior until late stages", "Bipolar disorder (manic episode) \u2014 characterized by elevated mood, pressured speech, decreased need for sleep, and grandiosity", "Behavioral variant Frontotemporal Dementia (bvFTD) \u2014 characterized by early personality and behavioral changes (disinhibition, apathy, loss of empathy, hyperorality, compulsive behaviors) with relative preservation of memory and visuospatial skills; caused by frontal and anterior temporal lobe degeneration", "Dementia with Lewy Bodies \u2014 characterized by fluctuating cognition, visual hallucinations, and spontaneous parkinsonism"]'::jsonb, 3, 'This patient''''s presentation is classic for **behavioral variant Frontotemporal Dementia (bvFTD)**, the most common subtype of FTD. Diagnostic criteria (Rascovsky criteria) require at least 3 of the following 6 features: (1) **Early behavioral disinhibition** — socially inappropriate behavior, loss of manners; (2) **Early apathy/inertia** — loss of motivation, reduced initiative; (3) **Early loss of sympathy/empathy** — diminished response to others'''' needs and feelings; (4) **Early perseverative, stereotyped, or compulsive/ritualistic behavior** — hoarding, repetitive movements; (5) **Hyperorality and dietary changes** — craving sweets, binge eating, attempting to eat inedible objects; (6) **Neuropsychological profile** showing **executive dysfunction with relative sparing of memory and visuospatial function**. Brain MRI shows **frontal and/or anterior temporal** atrophy, often asymmetric. FTD typically has an earlier onset (45-65 years) compared to AD (>65). Treatment is supportive: SSRIs for disinhibition and compulsive behaviors, trazodone for agitation. (Ref: Hazzard''''s Ch. 72; Rascovsky Criteria 2011)'),
